package org.achievementlabs.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.view.*;import android.widget.*;import androidx.webkit.WebViewAssetLoader;
import org.json.*;import java.io.*;import java.lang.ref.WeakReference;
public final class MainActivity extends Activity {
 static volatile JSONObject pendingLogin,pendingQR;WebView web;SessionEngine engine;boolean maintained;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff000000);getWindow().setNavigationBarColor(0xff111111);
  boolean preview=BuildConfig.DEBUG&&getIntent().getBooleanExtra("preview",false);String page=getIntent().getStringExtra("page");
  engine=((LabsApplication)getApplication()).engine(preview,page==null?"home":page);engine.screen=new WeakReference<>(this);
  web=new WebView(this);if(engine.preview)web.setLayerType(View.LAYER_TYPE_SOFTWARE,null);web.setBackgroundColor(0xff000000);FrameLayout host=new FrameLayout(this);host.setBackgroundColor(0xff000000);host.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(host);if(Build.VERSION.SDK_INT>=35){host.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout()),ime=insets.getInsets(android.view.WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));return android.view.WindowInsets.CONSUMED;});host.requestApplyInsets();}
  WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setJavaScriptCanOpenWindowsAutomatically(false);
  WebViewAssetLoader assets=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();
  web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){if(!maintained){maintained=true;new Handler(Looper.getMainLooper()).postDelayed(()->engine.work.execute(()->engine.maintain()),1000);}}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){WebResourceResponse local=assets.shouldInterceptRequest(r.getUrl());if(local!=null)return local;if(!r.isForMainFrame()&&"https".equals(r.getUrl().getScheme())){String h=r.getUrl().getHost();if(h!=null&&(h.endsWith(".xboxlive.com")||h.endsWith(".xbox.com")||h.endsWith(".xboxlive.cn")||h.endsWith(".microsoft.com")||h.equals("store-images.s-microsoft.com")))return null;}return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("https://appassets.androidplatform.net/assets/");}});
  web.addJavascriptInterface(new Bridge(),"LabsNative");web.loadUrl("https://appassets.androidplatform.net/assets/index.html");

 }
 void emit(String id,Object value,String error){if(web!=null)web.evaluateJavascript("window.nativeResult("+JSONObject.quote(id)+","+(value==null?"null":value.toString())+","+(error==null?"null":JSONObject.quote(error))+")",null);}
 void runtime(JSONObject state){if(web!=null)web.evaluateJavascript("window.runtimeUpdate("+state+")",null);}
 final class Bridge {
  @JavascriptInterface public void call(String id,String action,String data){if(id.length()>100||data.length()>2*1024*1024)return;engine.work.execute(()->{try{Object value=engine.handle(action,new JSONObject(data));engine.emit(id,value,null);}catch(Exception e){engine.notice=engine.safe(e);engine.emit(id,null,engine.notice);}engine.push();});}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK)return;engine.work.execute(()->{try{if(request==20){JSONObject qr=pendingQR;pendingQR=null;if(qr!=null)engine.verifyTransfer(qr);}if(request==21){JSONObject a=pendingLogin;pendingLogin=null;if(a!=null){if(engine.account!=null&&a.getString("xuid").equals(engine.account.getString("xuid")))a.put("eventToken",engine.account.optString("eventToken"));engine.replaceAccount(a);if(engine.prefs.optBoolean("autoRefresh",true))engine.refresh();}}engine.notice=request==20?engine.notice:"Microsoft sign-in connected.";}catch(Exception e){engine.notice=engine.safe(e);}try{engine.emit("external",engine.publicState(true),null);}catch(Exception ignored){}});}
 @Override protected void onResume(){super.onResume();engine.screen=new WeakReference<>(this);engine.foreground=true;if(BuildConfig.DEBUG&&engine.preview){if(getIntent().getBooleanExtra("backgroundTest",false))engine.work.execute(()->{try{engine.previewBackground();}catch(Exception e){engine.notice=engine.safe(e);}});if(getIntent().getBooleanExtra("timeoutTest",false)&&SessionService.active!=null)SessionService.active.onTimeout(0,0);}if(maintained)engine.work.execute(()->{try{engine.emit("external",engine.publicState(true),null);}catch(Exception ignored){}engine.maintain();});}
 @Override protected void onPause(){engine.background();super.onPause();}
 @Override protected void onDestroy(){if(engine.screen.get()==this)engine.screen.clear();if(web!=null){web.removeJavascriptInterface("LabsNative");web.destroy();web=null;}super.onDestroy();}
 @Override public void onBackPressed(){if(web!=null)web.evaluateJavascript("window.goBack()",null);else super.onBackPressed();}
}
